import fs from "node:fs";
import { agentsPath, contextFile } from "./paths";
import { atomicWrite } from "./store";
import { loadConfig, type BoardConfig } from "./boardyaml";
import { readEntries } from "./activity";
import type { Card } from "./card";

// Generated files the app owns (handoff §3.2 context files, §4.9 AGENTS.md). Both are generated
// only and never edited by hand.

export function renderAgents(cfg: BoardConfig): string {
  const stages = cfg.stages.join(", ");
  const areas = cfg.areas.join(", ");
  const boards = Object.keys(cfg.boards).join(", ");
  return `# AGENTS.md — kanban rules for Claude and Duet

This file is generated by Command Center from board.yaml and the writer rules (handoff §4.9).
Do not edit it by hand. Any Claude or Duet session pointed at this folder must follow these rules.

## Card files

- One file per card at cards/CC-XXXX.md, Markdown with YAML frontmatter (handoff §4.2).
- Stages: ${stages}.
- Areas (filter tags): ${areas}.
- Boards: ${boards}.

## Rules for every writer (handoff §4.7)

1. Write atomically: write a temp file in the same folder, then rename it over the card.
2. Set \`updated\` on every change. Re-read before writing; if \`updated\` moved, re-apply onto the
   current version instead of overwriting.
3. Never delete a card. Use the \`discarded\` stage. The app archives Done and discarded after 30 days.
4. Set \`last_actor\` and \`last_run\` on every change. Never write to log/; the app writes every log line.
5. Claude edits happen only inside a Sync run or in a chat when Josh asks — never on a timer.
6. Keep unknown fields as they are when rewriting a file.
7. Before creating a card from an email, note or EZ Binder change, check \`source_ref\` against cards/,
   new/ and archive/. Skip it if it already exists.
8. Limits on Claude and Duet:
   - No moves to \`done\` or \`discarded\`.
   - No changes to \`boards\`.
   - Card bodies are append only, never rewritten.
   - In a chat, Claude may go past these limits only when Josh asks for that specific change.

## Creating a card

Write a file without an \`id\` into new/. The app assigns the next id, moves it to cards/ and logs it.
`;
}

export function writeAgents(): void {
  const cfg = loadConfig();
  const next = renderAgents(cfg);
  const file = agentsPath();
  const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
  if (current !== next) atomicWrite(file, next);
}

// Context file for a card (handoff §3.2): the card's fields and notes, its project and linked deal
// or job summary, the last 10 history lines, and a pointer to AGENTS.md. Deals and EZ Binder jobs
// arrive in CC5/CC6, so their summaries are a placeholder line until then.
export function renderContext(card: Card): string {
  const history = readEntries(card.id)
    .slice(-10)
    .map((e) => `- ${e.at} · ${e.actor} · ${e.action}${e.run ? ` (${e.run})` : ""}`)
    .join("\n");
  const lines = [
    `# Context: ${card.id} — ${card.title}`,
    "",
    "Generated by Command Center (handoff §3.2). Do not edit by hand.",
    "",
    "## Fields",
    `- Stage: ${card.stage}`,
    `- Area: ${card.area}`,
    `- Boards: ${card.boards.join(", ")}`,
    `- Project: ${card.project ?? "(none)"}`,
    `- Due: ${card.due ?? "(none)"}`,
    card.waiting_on ? `- Waiting on: ${card.waiting_on} since ${card.waiting_since ?? "?"}` : "",
    "",
    "## Project / linked work",
    `- Project: ${card.project ?? "(none)"} — linked deal or EZ Binder job summary arrives in a later build.`,
    "",
    "## Notes",
    card.notes.trim() || "(none)",
    "",
    "## Last 10 history lines",
    history || "(none yet)",
    "",
    "## Rules",
    "See AGENTS.md in this folder for the rules Claude and Duet must follow.",
    "",
  ];
  return lines.filter((l) => l !== "").join("\n") + "\n";
}

export function writeContext(card: Card): void {
  atomicWrite(contextFile(card.id), renderContext(card));
}
